const payload = 'x'.repeat(9441);

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/sync') {
      return new Response(payload, {
        status: 200,
        headers: { 'content-type': 'application/octet-stream' },
      });
    }
    return new Response('not found', { status: 404 });
  },
};
